export interface LinearWebhookPayload {
  action: string;
  type: string;
  data: {
    id: string;
    title: string;
    url?: string;
    state?: string;
    comments: {
      edges: Array<{
        node: {
          id: string;
          content: string;
          createdAt: string;
        };
      }>;
      pageInfo: {
        endCursor: string;
        hasNextPage: boolean;
      };
    };
  };
  actor: {
    id: string;
    type: string;
    name: string;
    email: string;
  };
  createdAt: string;
  webhookTimestamp: number;
  organizationId: string;
  webhookId: string;
}

export interface ConnectorConfig {
  linearWebhookSecret: string;
  discordWebhookUrl: string;
  fetch?: typeof fetch;
}

export interface HandleResult {
  discordMessageId: string;
}

export async function handle(payload: LinearWebhookPayload, config: ConnectorConfig): Promise<HandleResult> {
  if (!payload.action || !payload.type || !payload.data) {
    throw new Error('Invalid payload: missing action, type, or data');
  }
  if (payload.action !== 'update' || payload.type !== 'Issue') {
    return { discordMessageId: '' };
  }
  const { data } = payload;
  if (!data.id || !data.title || !data.comments) {
    throw new Error('Invalid payload: data missing id, title, or comments');
  }
  if (data.state && data.state !== 'closed') {
    return { discordMessageId: '' };
  }
  const now = Date.now();
  if (Math.abs(now - payload.webhookTimestamp) > 60_000) {
    throw new Error('Webhook timestamp too old or in the future');
  }
  const comments = data.comments.edges.map((edge) => edge.node.content);
  if (data.comments.pageInfo.hasNextPage) {
    throw new Error('Pagination not supported: hasNextPage is true but Linear GraphQL API endpoint not configured');
  }
  let content = `**${data.title}**\n\n${comments.join('\n')}`;
  if (content.length > 2000) {
    content = content.slice(0, 1997) + '...';
  }
  const discordUrl = new URL(config.discordWebhookUrl);
  discordUrl.searchParams.set('wait', 'true');
  const fetchImpl = config.fetch ?? fetch;
  const response = await fetchImpl(discordUrl.toString(), {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ content }),
  });
  if (!response.ok) {
    throw new Error(`Discord API error: ${response.status} ${response.statusText} for ${discordUrl.toString()}`);
  }
  const result = (await response.json()) as { id: string };
  return { discordMessageId: result.id };
}

import { describe, it, expect, vi } from 'vitest';
import { SOURCE_EXAMPLE, contractFetch, fakeFetch, jsonResponse } from './fixtures';
import { handle, ConnectorConfig, LinearWebhookPayload } from './connector';

describe('contract', () => {
  it('handles the documented example payload', async () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date(1704113400000));
    const { fetch, calls } = contractFetch();
    const config: ConnectorConfig = {
      linearWebhookSecret: 'test-secret',
      discordWebhookUrl: 'https://discord.com/api/webhooks/123/abc',
      fetch,
    };
    const result = await handle(SOURCE_EXAMPLE as unknown as LinearWebhookPayload, config);
    expect(calls.length).toBeGreaterThan(0);
    expect(result.discordMessageId).toBe('123456789012345678');
    vi.useRealTimers();
  });
});

describe('handle', () => {
  it('posts a digest to Discord on happy path', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      if (req.url.includes('/api/webhooks/')) {
        return jsonResponse({ id: 'msg-123' }, 200);
      }
      return jsonResponse({ error: 'not found' }, 404);
    });
    const payload: LinearWebhookPayload = {
      ...SOURCE_EXAMPLE,
      data: {
        ...SOURCE_EXAMPLE.data,
        state: 'closed',
      },
    };
    const config: ConnectorConfig = {
      linearWebhookSecret: 'secret',
      discordWebhookUrl: 'https://discord.com/api/webhooks/123/abc',
      fetch,
    };
    const result = await handle(payload, config);
    expect(result.discordMessageId).toBe('msg-123');
    expect(calls[0].method).toBe('POST');
    expect(calls[0].json).toEqual({ content: expect.stringContaining('**Fix login bug**') });
  });

  it('throws when required field data.title is missing', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload = { ...SOURCE_EXAMPLE, data: { ...SOURCE_EXAMPLE.data, title: undefined } } as unknown as LinearWebhookPayload;
    const config: ConnectorConfig = { linearWebhookSecret: 's', discordWebhookUrl: 'https://discord.com/api/webhooks/1/2', fetch };
    await expect(handle(payload, config)).rejects.toThrow('Invalid payload: data missing id, title, or comments');
  });

  it('throws on non-2xx Discord response', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'Unauthorized' }, 401));
    const payload: LinearWebhookPayload = { ...SOURCE_EXAMPLE, data: { ...SOURCE_EXAMPLE.data, state: 'closed' } };
    const config: ConnectorConfig = { linearWebhookSecret: 's', discordWebhookUrl: 'https://discord.com/api/webhooks/1/2', fetch };
    await expect(handle(payload, config)).rejects.toThrow('Discord API error: 401 Unauthorized');
    expect(calls[0].url).toContain('/api/webhooks/');
  });

  it('throws when hasNextPage is true (pagination not supported)', async () => {
    const { fetch } = fakeFetch(() => jsonResponse({}, 200));
    const payload: LinearWebhookPayload = {
      ...SOURCE_EXAMPLE,
      data: {
        ...SOURCE_EXAMPLE.data,
        state: 'closed',
        comments: {
          edges: [],
          pageInfo: { endCursor: 'cursor', hasNextPage: true },
        },
      },
    };
    const config: ConnectorConfig = { linearWebhookSecret: 's', discordWebhookUrl: 'https://discord.com/api/webhooks/1/2', fetch };
    await expect(handle(payload, config)).rejects.toThrow('Pagination not supported');
  });

  it('skips posting when issue state is not closed', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({}, 200));
    const payload: LinearWebhookPayload = {
      ...SOURCE_EXAMPLE,
      data: { ...SOURCE_EXAMPLE.data, state: 'open' },
    };
    const config: ConnectorConfig = { linearWebhookSecret: 's', discordWebhookUrl: 'https://discord.com/api/webhooks/1/2', fetch };
    const result = await handle(payload, config);
    expect(result.discordMessageId).toBe('');
    expect(calls.length).toBe(0);
  });
});

